sys_script_include.script:
var LocationCoordinatesAjax = Class.create();

LocationCoordinatesAjax.prototype = Object.extendsObject(
    global.AbstractAjaxProcessor, {

    getCoordinates: function() {

        var location = this.getParameter('sysparm_location');

        if (!location) {
            return '';
        }

        var gr = new GlideRecord('x_snc_environmen_0_location_coordinates');

        gr.addQuery('location', location);
        gr.query();

        if (gr.next()) {

            return JSON.stringify({
				sys_id: gr.getUniqueValue(),
                latitude: gr.getValue('latitude'),
                longitude: gr.getValue('longitude'),
                state: gr.getValue('state'),
                district: gr.getValue('district')
            });
        }

        return '';
    },

    type: 'LocationCoordinatesAjax'
});
